use std::collections::HashSet;

pub fn contains(list: &Vec<i32>, element: i32) -> bool {
    list.iter().any(|&x| x == element)
}

pub fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> bool {
    if list1.is_empty() || list2.is_empty() {
        return false;
    }

    // Build a set from the smaller list to reduce memory usage.
    let (small, large) = if list1.len() <= list2.len() {
        (list1, list2)
    } else {
        (list2, list1)
    };

    let set: HashSet<i32> = small.iter().copied().collect();
    large.iter().any(|x| set.contains(x))
}